105	COMMENT ON COLUMN feeding.request_id IS '投料幂等键';
106	COMMENT ON COLUMN feeding.lot_id IS '所属缸次';
107	
108	CREATE TABLE IF NOT EXISTS weighing (
109	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
110	    feeding_id BIGINT NOT NULL,
111	    dye_code VARCHAR(64) NOT NULL,
112	    target_g DECIMAL(14, 4) NOT NULL,
113	    actual_g DECIMAL(14, 4) NOT NULL,
114	    deviation_pct DECIMAL(9, 6),
