123	COMMENT ON COLUMN weighing.actual_g IS '实际称量克重,单位g';
124	COMMENT ON COLUMN weighing.deviation_pct IS '称量偏差百分比=(实际-目标)/目标*100,绝对值>0.5拒绝投料(恰0.5合法);受控缸按补偿目标计算';
125	COMMENT ON COLUMN weighing.batch_no IS '受控缸投料所用染料批次号,空表示非受控缸旧语义称量';
126	COMMENT ON COLUMN weighing.factor_version IS '受控缸投料冻结的批次系数版本,空为非受控缸';
127	COMMENT ON COLUMN weighing.potency_factor IS '受控缸投料冻结的效价系数(线性模型),空为非受控缸';
128	COMMENT ON COLUMN weighing.base_target_g IS '受控缸补偿前原放大目标克重,单位g,空为非受控缸';
129	
130	CREATE TABLE IF NOT EXISTS lot_judgment (
131	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
132	    request_id VARCHAR(64) NOT NULL UNIQUE,
133	    lot_id BIGINT NOT NULL,
134	    round INT NOT NULL,
135	    delta_e DECIMAL(8, 4) NOT NULL,
136	    reference_lot_id BIGINT,
137	    reference_delta_e DECIMAL(8, 4),
138	    diff DECIMAL(9, 4),
139	    verdict VARCHAR(16) NOT NULL,
140	    judged_at TIMESTAMP NOT NULL
141	);
142	COMMENT ON COLUMN lot_judgment.request_id IS '判定幂等键';
143	COMMENT ON COLUMN lot_judgment.lot_id IS '被判定缸次';
144	COMMENT ON COLUMN lot_judgment.round IS '判定轮次:0首次出缸,1回修后复测';
145	COMMENT ON COLUMN lot_judgment.delta_e IS '本缸出缸ΔE';
146	COMMENT ON COLUMN lot_judgment.reference_lot_id IS '同配方对比缸次(缸差台账)';
147	COMMENT ON COLUMN lot_judgment.reference_delta_e IS '对比缸最近一次判定ΔE';
148	COMMENT ON COLUMN lot_judgment.diff IS '缸差=两缸ΔE之差的绝对值,>0.5须回修';
