162	-- 染料批次（效价补偿）：同一染料代码可登记多个批次，每批次系数独立版本化
163	CREATE TABLE IF NOT EXISTS dye_batch (
164	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
165	    batch_no VARCHAR(64) NOT NULL,
166	    dye_code VARCHAR(64) NOT NULL,
167	    factor_version INT NOT NULL,
168	    potency_factor DECIMAL(12, 6) NOT NULL,
169	    available_g DECIMAL(14, 3) NOT NULL,
170	    expire_at TIMESTAMP NOT NULL,
171	    active BOOLEAN NOT NULL DEFAULT TRUE,
172	    version INT NOT NULL DEFAULT 1,
173	    created_at TIMESTAMP NOT NULL,
174	    updated_at TIMESTAMP NOT NULL,
175	    CONSTRAINT uk_batch_factor_ver UNIQUE (batch_no, factor_version)
176	);
