178	COMMENT ON COLUMN dye_batch.dye_code IS '染料代码,与配方染化料编码匹配,错配整单拒绝';
179	COMMENT ON COLUMN dye_batch.factor_version IS '系数版本,从1开始,登记后每修订一次加1;投料/批准冻结具体版本';
180	COMMENT ON COLUMN dye_batch.potency_factor IS '效价系数(正数,仅按本题线性模型使用);补偿目标=原目标/系数,系数零或非有限数拒绝';
181	COMMENT ON COLUMN dye_batch.available_g IS '批次可用克重,单位g;受控投料原子扣减,两缸争同批不得超耗';
182	COMMENT ON COLUMN dye_batch.expire_at IS '有效期截止时刻;now<截止有效,恰在截止(相等)即失效';
183	COMMENT ON COLUMN dye_batch.active IS '当前系数版本是否有效;批次系数修订后旧版本FALSE,使未投料补偿批准失效';
184	COMMENT ON COLUMN dye_batch.version IS '批次登记聚合的乐观锁版本,从1开始,成功变更加1';
185	
186	-- 受控缸次效价补偿批准：投料前冻结每种染料的批次、系数版本与补偿目标
187	CREATE TABLE IF NOT EXISTS compensation (
188	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
189	    request_id VARCHAR(64) NOT NULL UNIQUE,
190	    lot_id BIGINT NOT NULL UNIQUE,
191	    status VARCHAR(16) NOT NULL,
192	    invalid_reason VARCHAR(255),
193	    version INT NOT NULL DEFAULT 1,
194	    created_at TIMESTAMP NOT NULL,
195	    updated_at TIMESTAMP NOT NULL
196	);
197	COMMENT ON COLUMN compensation.request_id IS '补偿审批幂等键;同键同参重放首次冻结结果,异参409,失败不占键';
198	COMMENT ON COLUMN compensation.lot_id IS '受控缸次主键,一个缸次至多一份补偿批准';
199	COMMENT ON COLUMN compensation.status IS '状态:FROZEN已冻结待投料/INVALID已失效/FED已投料(历史不追改)';
200	COMMENT ON COLUMN compensation.invalid_reason IS '失效原因;系数修订使未投料批准失效时记录,已投料历史不追改';
201	COMMENT ON COLUMN compensation.version IS '补偿批准乐观锁版本,从1开始,成功变更加1';
202	
203	CREATE TABLE IF NOT EXISTS compensation_item (
204	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
205	    compensation_id BIGINT NOT NULL,
206	    dye_code VARCHAR(64) NOT NULL,
207	    batch_no VARCHAR(64) NOT NULL,
208	    factor_version INT NOT NULL,
209	    potency_factor DECIMAL(12, 6) NOT NULL,
210	    base_target_g DECIMAL(14, 4) NOT NULL,
211	    compensated_target_g DECIMAL(14, 3) NOT NULL,
212	    CONSTRAINT uk_comp_item UNIQUE (compensation_id, dye_code)
213	);
214	COMMENT ON COLUMN compensation_item.compensation_id IS '所属补偿批准';
215	COMMENT ON COLUMN compensation_item.dye_code IS '染料代码,须与批次染料代码及配方项一致';
216	COMMENT ON COLUMN compensation_item.batch_no IS '冻结的染料批次号';
217	COMMENT ON COLUMN compensation_item.factor_version IS '冻结的批次系数版本';
218	COMMENT ON COLUMN compensation_item.potency_factor IS '冻结时刻的效价系数快照,批次修订不影响已投料历史';
219	COMMENT ON COLUMN compensation_item.base_target_g IS '补偿前原放大目标克重=浓度*浴比*布重,单位g';
