25	 * 先在同一事务内抢占 idempotent_request 唯一行，再执行业务，最后回写首次响应。
26	 * 同键同参返回首次结果（含首次状态码）；同键异参返回 409 且不执行任何业务动作（不扣库存）。
27	 */
28	@Component
29	public class IdempotencyService {
30	
31	    private final JdbcTemplate jdbc;
32	    private final ObjectMapper objectMapper;
33	    private final Clock clock;
34	
35	    public IdempotencyService(JdbcTemplate jdbc, ObjectMapper objectMapper, Clock clock) {
36	        this.jdbc = jdbc;
37	        this.objectMapper = objectMapper;
38	        this.clock = clock;
39	    }
40	
41	    /**
42	     * 在业务事务内执行幂等操作（调用方须处于事务中）。
43	     *
44	     * @param requestId 幂等键
45	     * @param operation 操作类型（COLOR_CHECK/SCHEDULE/MERGE/FEED/JUDGE）
46	     * @param payload   全部业务字段（不含 requestId 本身，指纹仍会覆盖它）
47	     * @param action    首次执行的业务动作
48	     * @return 首次结果或历史重放结果（replayed=true 表示重放）
49	     */
50	    public ServiceResult execute(String requestId, String operation, Map<String, Object> payload,
51	                                 java.util.function.Supplier<ServiceResult> action) {
52	        String fingerprint = fingerprint(operation, requestId, payload);
53	
54	        try {
55	            // 抢占幂等键：唯一索引保证并发时只有一个事务能插入；冲突方在 H2 行锁上等待胜者提交/回滚。
56	            jdbc.update("INSERT INTO idempotent_request "
57	                            + "(request_id, operation, fingerprint, response_status, response_body, created_at) "
58	                            + "VALUES (?, ?, ?, 0, NULL, ?)",
59	                    requestId, operation, fingerprint, Timestamp.from(Instant.now(clock)));
60	        } catch (DuplicateKeyException duplicate) {
61	            Map<String, Object> winner = readRecord(requestId);
62	            if (winner == null) {
63	                throw new IllegalStateException("幂等键抢占失败但查无记录: " + requestId);
64	            }
65	            if (!fingerprint.equals(winner.get("fingerprint"))) {
66	                throw new ApiException(HttpStatus.CONFLICT,
67	                        "requestId=" + requestId + " 已用于不同业务参数，拒绝处理（409 幂等冲突）");
68	            }
69	            return new ServiceResult((Integer) winner.get("status"),
70	                    readBody((String) winner.get("body")), true);
71	        }
72	
73	        ServiceResult result = action.get();
74	        jdbc.update("UPDATE idempotent_request SET response_status = ?, response_body = ? WHERE request_id = ?",
75	                result.status(), writeBody(result.body()), requestId);
76	        return result;
77	    }
78	
79	    private Map<String, Object> readRecord(String requestId) {
80	        return jdbc.query(
81	                "SELECT fingerprint, response_status, response_body FROM idempotent_request WHERE request_id = ?",
82	                rs -> {
83	                    if (!rs.next()) {
84	                        return null;
85	                    }
86	                    Map<String, Object> row = new HashMap<>();
87	                    row.put("fingerprint", rs.getString("fingerprint"));
88	                    row.put("status", rs.getInt("response_status"));
89	                    row.put("body", rs.getString("response_body"));
90	                    return row;
91	                },
92	                requestId);
93	    }
94	
95	    /**
96	     * 计算指纹：operation 与 requestId 在内，业务参数递归排序键并规范化数值文本。
97	     */
98	    public String fingerprint(String operation, String requestId, Map<String, Object> payload) {
99	        TreeMap<String, Object> canonical = new TreeMap<>();
100	        canonical.put("operation", operation);
101	        canonical.put("requestId", requestId);
102	        canonical.put("payload", normalize(payload));
103	        try {
104	            String json = objectMapper.writeValueAsString(canonical);
105	            MessageDigest md = MessageDigest.getInstance("SHA-256");
106	            byte[] digest = md.digest(json.getBytes(StandardCharsets.UTF_8));
107	            StringBuilder sb = new StringBuilder();
108	            for (byte b : digest) {
109	                sb.append(String.format("%02x", b));
110	            }
111	            return sb.toString();
112	        } catch (JsonProcessingException e) {
113	            throw new IllegalStateException("幂等指纹序列化失败", e);
114	        } catch (Exception e) {
115	            throw new IllegalStateException("SHA-256 不可用", e);
116	        }
117	    }
118	
119	    private Object normalize(Object value) {
120	        if (value instanceof Map<?, ?> map) {
121	            TreeMap<String, Object> sorted = new TreeMap<>();
122	            map.forEach((k, v) -> sorted.put(String.valueOf(k), normalize(v)));
123	            return sorted;
124	        }
125	        if (value instanceof List<?> list) {
126	            return list.stream().map(this::normalize).toList();
127	        }
128	        if (value instanceof BigDecimal bd) {
129	            return bd.stripTrailingZeros().toPlainString();
130	        }
131	        return value;
132	    }
133	
134	    @SuppressWarnings("unchecked")
135	    private Map<String, Object> readBody(String json) {
136	        if (json == null || json.isBlank()) {
137	            return Map.of();
138	        }
139	        try {
140	            return objectMapper.readValue(json, Map.class);
141	        } catch (JsonProcessingException e) {
142	            throw new IllegalStateException("幂等响应反序列化失败", e);
143	        }
144	    }
145	
146	    private String writeBody(Map<String, Object> body) {
147	        try {
148	            return objectMapper.writeValueAsString(body);
149	        } catch (JsonProcessingException e) {
150	            throw new IllegalStateException("幂等响应序列化失败", e);
151	        }
152	    }
153	}
