1	package com.example.starter.service;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	import java.sql.Timestamp;
6	import java.time.Clock;
7	import java.time.Instant;
8	import java.util.ArrayList;
9	import java.util.LinkedHashMap;
10	import java.util.LinkedHashSet;
11	import java.util.List;
12	import java.util.Map;
13	import java.util.Set;
14	
15	import org.springframework.dao.DuplicateKeyException;
16	import org.springframework.http.HttpStatus;
17	import org.springframework.jdbc.core.JdbcTemplate;
18	import org.springframework.stereotype.Service;
19	import org.springframework.transaction.annotation.Transactional;
20	
21	import com.example.starter.api.dto.CompensationItemInput;
22	import com.example.starter.api.dto.CompensationRequest;
23	import com.example.starter.api.dto.RegisterBatchRequest;
24	import com.example.starter.api.dto.ReviseBatchRequest;
25	import com.example.starter.domain.CompensationStatus;
26	import com.example.starter.support.ApiException;
27	
28	/**
29	 * 染料批次效价补偿服务。
30	 *
31	 * <p>线性模型：补偿目标克重 = 原放大目标 / 效价系数（十进制计算，四舍五入到三位小数）。
32	 * 批次系数按版本登记与修订；修订使旧版本失效，并使引用该批次的未投料补偿批准失效，
33	 * 已投料历史冻结快照不追改。补偿批准冻结批次、系数版本与补偿目标，不修改已发布基础配方。
34	 */
35	@Service
36	public class BatchCompensationService {
37	
38	    /** 补偿目标保留三位小数（四舍五入）。 */
39	    static final int COMP_SCALE = 3;
40	    /** 原放大目标保留位数与旧投料语义一致。 */
41	    static final int BASE_SCALE = 4;
42	
43	    private final JdbcTemplate jdbc;
44	    private final IdempotencyService idempotency;
45	    private final Clock clock;
46	
47	    public BatchCompensationService(JdbcTemplate jdbc, IdempotencyService idempotency, Clock clock) {
48	        this.jdbc = jdbc;
49	        this.idempotency = idempotency;
50	        this.clock = clock;
51	    }
52	
53	    private Timestamp nowTs() {
54	        return Timestamp.from(Instant.now(clock));
55	    }
56	
57	    // ------------------------------------------------------------------
58	    // 批次登记：首个系数版本从 1 开始，携带 expectedVersion=1
59	    // ------------------------------------------------------------------
60	
61	    @Transactional
62	    public ServiceResult registerBatch(RegisterBatchRequest req) {
63	        Map<String, Object> payload = new LinkedHashMap<>();
64	        payload.put("batchNo", req.batchNo());
65	        payload.put("dyeCode", req.dyeCode());
66	        payload.put("potencyFactor", req.potencyFactor());
67	        payload.put("availableG", req.availableG());
68	        payload.put("expireAt", req.expireAt().toInstant());
69	        payload.put("expectedVersion", req.expectedVersion());
70	
71	        return idempotency.execute(req.requestId(), "BATCH_REGISTER", payload, () -> {
72	            if (req.expectedVersion() == null || req.expectedVersion() != 1) {
73	                throw new ApiException(HttpStatus.BAD_REQUEST,
74	                        "批次登记为新建聚合，expectedVersion 必须为 1");
75	            }
76	            assertFinitePositive(req.potencyFactor(), "效价系数");
77	            if (req.availableG() == null || req.availableG().signum() <= 0) {
78	                throw new ApiException(HttpStatus.BAD_REQUEST, "可用克重必须为正数");
79	            }
80	            Integer dyeExists = jdbc.query("SELECT 1 FROM dye WHERE code = ?",
81	                    rs -> rs.next() ? 1 : null, req.dyeCode());
82	            if (dyeExists == null) {
83	                throw new ApiException(HttpStatus.BAD_REQUEST,
84	                        "染料代码 " + req.dyeCode() + " 不存在，拒绝登记批次");
85	            }
86	            Timestamp now = nowTs();
87	            try {
88	                jdbc.update("INSERT INTO dye_batch (batch_no, dye_code, factor_version, potency_factor, "
89	                        + "available_g, expire_at, active, version, created_at, updated_at) "
90	                        + "VALUES (?, ?, 1, ?, ?, ?, TRUE, 1, ?, ?)",
91	                        req.batchNo(), req.dyeCode(), req.potencyFactor(), req.availableG(),
92	                        Timestamp.from(req.expireAt().toInstant()), now, now);
93	            } catch (DuplicateKeyException dup) {
94	                throw new ApiException(HttpStatus.CONFLICT,
95	                        "染料批次 " + req.batchNo() + " 已登记；修订系数请使用修订接口");
96	            }
97	            return ServiceResult.created(batchView(req.batchNo()));
98	        });
99	    }
100	
101	    // ------------------------------------------------------------------
102	    // 批次系数修订：旧版本失效、新版本号加 1；未投料补偿批准随之失效
103	    // ------------------------------------------------------------------
104	
105	    @Transactional
106	    public ServiceResult reviseBatch(ReviseBatchRequest req) {
107	        Map<String, Object> payload = new LinkedHashMap<>();
108	        payload.put("batchNo", req.batchNo());
109	        payload.put("potencyFactor", req.potencyFactor());
110	        payload.put("availableG", req.availableG());
111	        payload.put("expireAt", req.expireAt().toInstant());
112	        payload.put("expectedVersion", req.expectedVersion());
113	
114	        return idempotency.execute(req.requestId(), "BATCH_REVISE", payload, () -> {
115	            assertFinitePositive(req.potencyFactor(), "效价系数");
116	            if (req.availableG() == null || req.availableG().signum() <= 0) {
117	                throw new ApiException(HttpStatus.BAD_REQUEST, "可用克重必须为正数");
118	            }
119	            Map<String, Object> current = latestBatch(req.batchNo());
120	            int currentVersion = ((Number) current.get("version")).intValue();
121	            if (req.expectedVersion() == null || req.expectedVersion() != currentVersion) {
122	                throw new ApiException(HttpStatus.CONFLICT,
123	                        "批次 " + req.batchNo() + " 版本冲突：expectedVersion=" + req.expectedVersion()
124	                                + "，当前版本=" + currentVersion);
125	            }
126	            int nextFactorVersion = ((Number) current.get("factor_version")).intValue() + 1;
127	            Timestamp now = nowTs();
128	
129	            // 统一加锁顺序 compensation → dye_batch：先锁引用该批次的未投料批准，再改批次行，
130	            // 与受控投料（先锁补偿、再扣批次余量）保持一致，避免互锁死锁。
131	            List<Map<String, Object>> frozenRows = jdbc.queryForList(
132	                    "SELECT c.id, c.version FROM compensation c JOIN compensation_item ci ON ci.compensation_id = c.id "
133	                            + "WHERE ci.batch_no = ? AND c.status = ? FOR UPDATE",
134	                    req.batchNo(), CompensationStatus.FROZEN.name());
135	
136	            jdbc.update("UPDATE dye_batch SET active = FALSE, updated_at = ? WHERE batch_no = ?",
137	                    now, req.batchNo());
138	            try {
139	                jdbc.update("INSERT INTO dye_batch (batch_no, dye_code, factor_version, potency_factor, "
140	                        + "available_g, expire_at, active, version, created_at, updated_at) "
141	                        + "VALUES (?, ?, ?, ?, ?, ?, TRUE, ?, ?, ?)",
142	                        req.batchNo(), current.get("dye_code"), nextFactorVersion, req.potencyFactor(),
143	                        req.availableG(), Timestamp.from(req.expireAt().toInstant()),
144	                        currentVersion + 1, now, now);
145	            } catch (DuplicateKeyException dup) {
146	                throw new ApiException(HttpStatus.CONFLICT,
147	                        "批次 " + req.batchNo() + " 系数版本 " + nextFactorVersion + " 已存在（并发修订）");
148	            }
149	
150	            // 系数修订：引用该批次的未投料(FROZEN)补偿批准整单失效；FED 历史冻结不追改。
151	            for (Map<String, Object> row : frozenRows) {
152	                int updated = jdbc.update(
153	                        "UPDATE compensation SET status = ?, invalid_reason = ?, version = version + 1, updated_at = ? "
154	                                + "WHERE id = ? AND status = ? AND version = ?",
155	                        CompensationStatus.INVALID.name(),
156	                        "批次 " + req.batchNo() + " 系数修订至 v" + nextFactorVersion + "，未投料批准失效",
157	                        now, row.get("id"), CompensationStatus.FROZEN.name(), row.get("version"));
158	                if (updated == 0) {
159	                    // 并发下被投料或被其它修订抢先处理：整单回滚重试，避免错误宣告失效。
160	                    throw new ApiException(HttpStatus.CONFLICT,
161	                            "批次 " + req.batchNo() + " 修订与并发投料冲突，请重试");
162	                }
163	            }
164	            return ServiceResult.ok(batchView(req.batchNo()));
165	        });
166	    }
167	
168	    // ------------------------------------------------------------------
169	    // 补偿审批：冻结批次/系数/补偿目标，不修改已发布基础配方
170	    // ------------------------------------------------------------------
171	
172	    @Transactional
173	    public ServiceResult approveCompensation(CompensationRequest req) {
174	        List<Map<String, Object>> itemPayload = new ArrayList<>();
175	        for (CompensationItemInput item : req.items()) {
176	            Map<String, Object> entry = new LinkedHashMap<>();
177	            entry.put("dyeCode", item.dyeCode());
178	            entry.put("batchNo", item.batchNo());
179	            entry.put("factorVersion", item.factorVersion());
180	            itemPayload.add(entry);
181	        }
182	        // 集合按染料代码排序后入指纹：交换提交顺序不产生异参冲突；JSON 结构编码保证含分隔符文本可区分。
183	        itemPayload.sort((a, b) -> String.valueOf(a.get("dyeCode")).compareTo(String.valueOf(b.get("dyeCode"))));
184	        Map<String, Object> payload = new LinkedHashMap<>();
185	        payload.put("lotNo", req.lotNo());
186	        payload.put("expectedVersion", req.expectedVersion());
187	        payload.put("items", itemPayload);
188	
189	        return idempotency.execute(req.requestId(), "COMPENSATION_APPROVE", payload, () -> {
190	            Map<String, Object> lot = requireLot(req.lotNo());
191	            if (!Boolean.TRUE.equals(lot.get("controlled"))) {
192	                throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
193	                        "缸次 " + req.lotNo() + " 为旧非受控缸次，无需也不能办理效价补偿批准");
194	            }
195	            if (!"CREATED".equals(lot.get("status"))) {
196	                throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
197	                        "受控缸次 " + req.lotNo() + " 当前状态 " + lot.get("status") + "，不能再办理补偿批准");
198	            }
199	
200	            Long recipeVersionId = jdbc.queryForObject(
201	                    "SELECT id FROM recipe WHERE recipe_code = ? AND version = ?",
202	                    Long.class, lot.get("recipe_code"), lot.get("recipe_version"));
203	            List<Map<String, Object>> recipeItems = jdbc.queryForList(
204	                    "SELECT dye_code, dosage_gpl FROM recipe_item WHERE recipe_id = ? ORDER BY dye_code",
205	                    recipeVersionId);
206	
207	            Set<String> requested = new LinkedHashSet<>();
208	            Map<String, CompensationItemInput> inputByDye = new LinkedHashMap<>();
209	            for (CompensationItemInput item : req.items()) {
210	                if (!requested.add(item.dyeCode())) {
211	                    throw new ApiException(HttpStatus.BAD_REQUEST,
212	                            "补偿清单中染料 " + item.dyeCode() + " 重复");
213	                }
214	                inputByDye.put(item.dyeCode(), item);
215	            }
216	            Set<String> required = new LinkedHashSet<>();
217	            for (Map<String, Object> ri : recipeItems) {
218	                required.add((String) ri.get("dye_code"));
219	            }
220	            if (!requested.equals(required)) {
221	                Set<String> missing = new LinkedHashSet<>(required);
222	                missing.removeAll(requested);
223	                Set<String> extra = new LinkedHashSet<>(requested);
224	                extra.removeAll(required);
225	                throw new ApiException(HttpStatus.BAD_REQUEST,
226	                        "补偿染料集合与已发布配方不一致，缺少 " + missing + "、多余 " + extra + "，整单拒绝");
227	            }
228	
229	            BigDecimal ratio = (BigDecimal) lot.get("liquor_ratio");
230	            BigDecimal fabricKg = (BigDecimal) lot.get("fabric_weight_kg");
231	            Timestamp now = nowTs();
232	            List<Map<String, Object>> frozenItems = new ArrayList<>();
233	            for (Map<String, Object> ri : recipeItems) {
234	                String dyeCode = (String) ri.get("dye_code");
235	                CompensationItemInput input = inputByDye.get(dyeCode);
236	                Map<String, Object> batch = requireBatchVersion(input.batchNo(), input.factorVersion());
237	                if (!dyeCode.equals(batch.get("dye_code"))) {
238	                    throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
239	                            "染料代码错配：批次 " + input.batchNo() + " 属于 " + batch.get("dye_code")
240	                                    + "，不能用于配方染料 " + dyeCode + "，整单拒绝");
241	                }
242	                if (!Boolean.TRUE.equals(batch.get("active"))) {
243	                    throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
244	                            "批次 " + input.batchNo() + " 系数版本 v" + input.factorVersion()
245	                                    + " 已被修订失效，请引用最新版本，整单拒绝");
246	                }
247	                BigDecimal factor = (BigDecimal) batch.get("potency_factor");
248	                assertFinitePositive(factor, "效价系数");
249	                Timestamp expireAt = (Timestamp) batch.get("expire_at");
250	                if (!nowTs().before(expireAt)) {
251	                    throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
252	                            "批次 " + input.batchNo() + " 已到/超过有效截止 " + expireAt.toInstant()
253	                                    + "（恰在截止即失效），整单拒绝");
254	                }
255	                BigDecimal baseTarget = ((BigDecimal) ri.get("dosage_gpl")).multiply(ratio).multiply(fabricKg)
256	                        .setScale(BASE_SCALE, RoundingMode.HALF_UP);
257	                BigDecimal compensated = baseTarget.divide(factor, COMP_SCALE, RoundingMode.HALF_UP);
258	                BigDecimal available = (BigDecimal) batch.get("available_g");
259	                if (available.compareTo(compensated) < 0) {
260	                    throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
261	                            "批次 " + input.batchNo() + " 余量 " + available + "g 不足补偿目标 "
262	                                    + compensated + "g，整单拒绝");
263	                }
264	                Map<String, Object> frozen = new LinkedHashMap<>();
265	                frozen.put("dyeCode", dyeCode);
266	                frozen.put("batchNo", input.batchNo());
267	                frozen.put("factorVersion", input.factorVersion());
268	                frozen.put("potencyFactor", factor);
269	                frozen.put("baseTargetG", baseTarget);
270	                frozen.put("compensatedTargetG", compensated);
271	                frozenItems.add(frozen);
272	            }
273	
274	            Map<String, Object> existing = jdbc.queryForList(
275	                    "SELECT id, status, version FROM compensation WHERE lot_id = ? FOR UPDATE", lot.get("id"))
276	                    .stream().findFirst().orElse(null);
277	            Long compensationId;
278	            int resultingVersion;
279	            if (existing == null) {
280	                if (req.expectedVersion() == null || req.expectedVersion() != 1) {
281	                    throw new ApiException(HttpStatus.CONFLICT,
282	                            "缸次 " + req.lotNo() + " 尚无补偿批准，expectedVersion 必须为 1");
283	                }
284	                try {
285	                    jdbc.update("INSERT INTO compensation (request_id, lot_id, status, invalid_reason, version, "
286	                            + "created_at, updated_at) VALUES (?, ?, ?, NULL, 1, ?, ?)",
287	                            req.requestId(), lot.get("id"), CompensationStatus.FROZEN.name(), now, now);
288	                } catch (DuplicateKeyException concurrentInsert) {
289	                    throw new ApiException(HttpStatus.CONFLICT,
290	                            "缸次 " + req.lotNo() + " 补偿批准并发创建，请携带当前版本重试");
291	                }
292	                compensationId = jdbc.queryForObject(
293	                        "SELECT id FROM compensation WHERE lot_id = ?", Long.class, lot.get("id"));
294	                resultingVersion = 1;
295	            } else {
296	                if (CompensationStatus.FED.name().equals(existing.get("status"))) {
297	                    throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
298	                            "缸次 " + req.lotNo() + " 已投料，补偿冻结为历史，不允许重新审批");
299	                }
300	                int expected = req.expectedVersion() == null ? -1 : req.expectedVersion();
301	                int currentVersion = ((Number) existing.get("version")).intValue();
302	                if (expected != currentVersion) {
303	                    throw new ApiException(HttpStatus.CONFLICT,
304	                            "补偿批准版本冲突：expectedVersion=" + expected + "，当前版本=" + currentVersion);
305	                }
306	                compensationId = ((Number) existing.get("id")).longValue();
307	                jdbc.update("DELETE FROM compensation_item WHERE compensation_id = ?", compensationId);
308	                resultingVersion = currentVersion + 1;
309	                int updated = jdbc.update("UPDATE compensation SET request_id = ?, status = ?, invalid_reason = NULL, "
310	                        + "version = ?, updated_at = ? WHERE id = ? AND version = ?",
311	                        req.requestId(), CompensationStatus.FROZEN.name(), resultingVersion, now,
312	                        compensationId, currentVersion);
313	                if (updated != 1) {
314	                    throw new ApiException(HttpStatus.CONFLICT,
315	                            "补偿批准 " + req.lotNo() + " 并发变更，版本已更新，请携带新版本重试");
316	                }
317	            }
318	
319	            for (Map<String, Object> f : frozenItems) {
320	                jdbc.update("INSERT INTO compensation_item (compensation_id, dye_code, batch_no, factor_version, "
321	                        + "potency_factor, base_target_g, compensated_target_g) VALUES (?, ?, ?, ?, ?, ?, ?)",
322	                        compensationId, f.get("dyeCode"), f.get("batchNo"), f.get("factorVersion"),
323	                        f.get("potencyFactor"), f.get("baseTargetG"), f.get("compensatedTargetG"));
324	            }
325	            return ServiceResult.created(compensationView(req.lotNo(), resultingVersion));
326	        });
327	    }
328	
329	    // ------------------------------------------------------------------
330	    // 证据查询
331	    // ------------------------------------------------------------------
332	
333	    @Transactional(readOnly = true)
334	    public ServiceResult getBatch(String batchNo) {
335	        return ServiceResult.ok(batchView(batchNo));
336	    }
337	
338	    @Transactional(readOnly = true)
339	    public ServiceResult getCompensation(String lotNo) {
340	        requireLot(lotNo);
341	        Map<String, Object> row = jdbc.queryForList(
342	                "SELECT id, request_id, status, invalid_reason, version, created_at, updated_at "
343	                        + "FROM compensation WHERE lot_id = (SELECT id FROM lot WHERE lot_no = ?)",
344	                lotNo).stream().findFirst().orElse(null);
345	        if (row == null) {
346	            throw new ApiException(HttpStatus.NOT_FOUND, "缸次 " + lotNo + " 尚无补偿批准");
347	        }
348	        int version = ((Number) row.get("version")).intValue();
349	        return ServiceResult.ok(compensationView(lotNo, version));
350	    }
351	
352	    // ------------------------------------------------------------------
353	    // 内部辅助
354	    // ------------------------------------------------------------------
355	
356	    private void assertFinitePositive(BigDecimal value, String label) {
357	        if (value == null) {
358	            throw new ApiException(HttpStatus.BAD_REQUEST, label + "不能为空");
359	        }
360	        if (value.signum() <= 0) {
361	            throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
362	                    label + "必须为正数，零/负数整单拒绝；实际=" + value.toPlainString());
363	        }
364	    }
365	
366	    private Map<String, Object> latestBatch(String batchNo) {
367	        Map<String, Object> row = jdbc.queryForList(
368	                "SELECT * FROM dye_batch WHERE batch_no = ? ORDER BY factor_version DESC LIMIT 1",
369	                batchNo).stream().findFirst().orElse(null);
370	        if (row == null) {
371	            throw new ApiException(HttpStatus.NOT_FOUND, "染料批次 " + batchNo + " 不存在");
372	        }
373	        return row;
374	    }
375	
376	    private Map<String, Object> requireBatchVersion(String batchNo, int factorVersion) {
377	        List<Map<String, Object>> rows = jdbc.queryForList(
378	                "SELECT * FROM dye_batch WHERE batch_no = ? AND factor_version = ?", batchNo, factorVersion);
379	        if (rows.isEmpty()) {
380	            throw new ApiException(HttpStatus.NOT_FOUND,
381	                    "染料批次 " + batchNo + " 系数版本 v" + factorVersion + " 不存在");
382	        }
383	        return rows.get(0);
384	    }
385	
386	    private Map<String, Object> requireLot(String lotNo) {
387	        List<Map<String, Object>> rows = jdbc.queryForList("SELECT * FROM lot WHERE lot_no = ?", lotNo);
388	        if (rows.isEmpty()) {
389	            throw new ApiException(HttpStatus.NOT_FOUND, "缸次 " + lotNo + " 不存在");
390	        }
391	        return rows.get(0);
392	    }
393	
394	    private Map<String, Object> batchView(String batchNo) {
395	        List<Map<String, Object>> rows = jdbc.queryForList(
396	                "SELECT * FROM dye_batch WHERE batch_no = ? ORDER BY factor_version", batchNo);
397	        if (rows.isEmpty()) {
398	            throw new ApiException(HttpStatus.NOT_FOUND, "染料批次 " + batchNo + " 不存在");
399	        }
400	        Map<String, Object> current = rows.get(rows.size() - 1);
401	        Map<String, Object> view = new LinkedHashMap<>();
402	        view.put("batchNo", current.get("batch_no"));
403	        view.put("dyeCode", current.get("dye_code"));
404	        view.put("factorVersion", current.get("factor_version"));
405	        view.put("potencyFactor", current.get("potency_factor"));
406	        view.put("availableG", current.get("available_g"));
407	        view.put("expireAt", ((Timestamp) current.get("expire_at")).toInstant().toString());
408	        view.put("active", current.get("active"));
409	        view.put("version", current.get("version"));
410	        List<Map<String, Object>> history = new ArrayList<>();
411	        for (Map<String, Object> r : rows) {
412	            Map<String, Object> h = new LinkedHashMap<>();
413	            h.put("factorVersion", r.get("factor_version"));
414	            h.put("potencyFactor", r.get("potency_factor"));
415	            h.put("availableG", r.get("available_g"));
416	            h.put("expireAt", ((Timestamp) r.get("expire_at")).toInstant().toString());
417	            h.put("active", r.get("active"));
418	            history.add(h);
419	        }
420	        view.put("factorHistory", history);
421	        return view;
422	    }
423	
424	    private Map<String, Object> compensationView(String lotNo, int version) {
425	        Map<String, Object> comp = jdbc.queryForMap(
426	                "SELECT * FROM compensation WHERE lot_id = (SELECT id FROM lot WHERE lot_no = ?) AND version = ?",
427	                lotNo, version);
428	        Map<String, Object> view = new LinkedHashMap<>();
429	        view.put("requestId", comp.get("request_id"));
430	        view.put("lotNo", lotNo);
431	        view.put("status", comp.get("status"));
432	        view.put("invalidReason", comp.get("invalid_reason"));
433	        view.put("version", comp.get("version"));
434	        view.put("createdAt", ((Timestamp) comp.get("created_at")).toInstant().toString());
435	        view.put("updatedAt", ((Timestamp) comp.get("updated_at")).toInstant().toString());
436	        List<Map<String, Object>> items = new ArrayList<>();
437	        jdbc.query("SELECT dye_code, batch_no, factor_version, potency_factor, base_target_g, compensated_target_g "
438	                + "FROM compensation_item WHERE compensation_id = ? ORDER BY dye_code", rs -> {
439	            Map<String, Object> item = new LinkedHashMap<>();
440	            item.put("dyeCode", rs.getString("dye_code"));
441	            item.put("batchNo", rs.getString("batch_no"));
442	            item.put("factorVersion", rs.getInt("factor_version"));
443	            item.put("potencyFactor", rs.getBigDecimal("potency_factor"));
444	            item.put("baseTargetG", rs.getBigDecimal("base_target_g"));
445	            item.put("compensatedTargetG", rs.getBigDecimal("compensated_target_g"));
446	            items.add(item);
447	        }, comp.get("id"));
448	        view.put("items", items);
449	
450	        // 实时有效性：FROZEN 且各冻结批次版本仍 active 且未到截止。
451	        boolean liveValid = CompensationStatus.FROZEN.name().equals(comp.get("status"));
452	        Timestamp now = nowTs();
453	        if (liveValid) {
454	            for (Map<String, Object> item : items) {
455	                Map<String, Object> batch = jdbc.queryForMap(
456	                        "SELECT active, expire_at FROM dye_batch WHERE batch_no = ? AND factor_version = ?",
457	                        item.get("batchNo"), item.get("factorVersion"));
458	                if (!Boolean.TRUE.equals(batch.get("active")) || !now.before((Timestamp) batch.get("expire_at"))) {
459	                    liveValid = false;
460	                    break;
461	                }
462	            }
463	        }
464	        view.put("currentlyValid", liveValid);
465	        return view;
466	    }
467	}
