    }

    Map<String, Object> body = new LinkedHashMap<>();
    body.put("sourceLotNo", source.get("lot_no"));
    body.put("sourceStatus", source.get("status"));
    body.put("sourceFabricWeightKg", source.get("fabric_weight_kg"));
