    List<BigDecimal> values = jdbc.query(
            "SELECT delta_e FROM lot_judgment WHERE lot_id = ? ORDER BY id DESC LIMIT 1",
            (rs, rowNum) -> rs.getBigDecimal("delta_e"), lotId);

