        // 子缸重新首次投料：拒绝，且库存不动。
        ResponseEntity<Map> refeed = post("/api/feedings", Map.of(
                "requestId", "cf2-refeed", "lotNo", "LC1",
                "weighings", List.of(
                        Map.of("dyeCode", "D-RED", "actualG", new BigDecimal("800.0000")),
