        // 子缸自身分缸版本默认为 1（元数据存在），但它们已是 FED；本题不要求对子缸再分缸。
        Map<String, Object> child = rest.getForObject(url("/api/lots/LC1"), Map.class);
        assertEquals(1, child.get("splitVersion"));
        assertEquals("FED", child.get("status"));
    }
